def _cursor_value_int(value: object) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= ONBOARDING_MAX_CURSOR:
        raise ValueError('cursor must be a non-bool integer between 0 and 2^63-1')
